/* Which wallpaper is on the walls.
 *
 * Loaded in the <head> of every page (right after sky.js), so the chosen
 * wallpaper is up before the page is drawn: it sets <html data-wp="...">,
 * and style.css turns that into the pattern (the patterns themselves are
 * generated by tools/build_wallpapers.py). The kitchen and the gallery have
 * wallpapers of their own, so they ignore it.
 *
 * The choice is made with the sample fan on the home page (wallpaper-
 * picker.js) and remembered in this browser (localStorage), so every room
 * with the cottage wallpaper shows it, on this visit and the next. Other tabs
 * of the site that are open at the time follow along too.
 */
(function () {
  "use strict";

  var KEY = "sg-wallpaper";
  var WALLPAPERS = [
    { id: "garden",     name: "garden stripe",  note: "the cottage's own: soft stripes and little sprigs" },
    { id: "wildflower", name: "wildflower",     note: "a meadow of tiny blossoms" },
    { id: "woodland",   name: "woodland",       note: "toadstools, ferns, acorns and a snail" },
    { id: "gingham",    name: "picnic gingham", note: "a rose-pink check" },
    { id: "wisteria",   name: "wisteria",       note: "a garden trellis dripping with wisteria" },
    { id: "moonlit",    name: "moonlit",        note: "crescent moons and sparkles, gold at night" }
  ];
  var root = document.documentElement;

  function known(id) {
    for (var i = 0; i < WALLPAPERS.length; i++) if (WALLPAPERS[i].id === id) return true;
    return false;
  }
  function stored() {
    try { return localStorage.getItem(KEY); } catch (e) { return null; }
  }

  var current = known(stored()) ? stored() : "garden";
  root.setAttribute("data-wp", current);

  var api = {
    list: WALLPAPERS,
    get: function () { return current; },
    // put a wallpaper up (no animation: the picker does the hanging first)
    set: function (id) {
      if (!known(id)) return;
      current = id;
      root.setAttribute("data-wp", id);
      try { localStorage.setItem(KEY, id); } catch (e) {}
      if (api.onchange) api.onchange(id);
    },
    onchange: null
  };

  // changed in another tab of the site: follow it here too
  window.addEventListener("storage", function (e) {
    if (e.key !== KEY || !known(e.newValue) || e.newValue === current) return;
    current = e.newValue;
    root.setAttribute("data-wp", current);
    if (api.onchange) api.onchange(current);
  });

  window.Wallpaper = api;
})();
